//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//	NAME: 		HE_VFD_AnaContr
//	CREATOR:	    William Veim                                                                                                                                                                                                                                              
//                                                                                                                                                                                                                                                                                                                            
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//  VERSION LOG:                                                                                                                                                                                                                                                                                                   
//	VERSION				DATE					SIGN					DESCRIPTION                                                                                                                                                                                                                                 
//  1.1.0					2023-10-18			WV						Draft
//===============================================================================================================================
//
//		DESCRIPTION:
//
//		FUNCTION:
//
//
//===============================================================================================================================

(*************************************************************************
 *	Update Inputs
 *************************************************************************)
 
// Config Parameter
Ext_VFD.EXT_Engineering.Auto_Visible:= 							Cfg_Auto_InUse;
Ext_VFD.EXT_General.LocationIndex[0]:=							Cfg_MainLocation; //First index / main location is forced; remaining tree optional can be set in SCADA
Ext_VFD.EXT_Engineering.ReverseRunning_Visible:=			FALSE;
Ext_VFD.EXT_Engineering.LCfg_Autotune_Visible:=			FALSE;
Ext_VFD.EXT_Engineering.LCfg_MotorData_Visible:=			FALSE;
Ext_VFD.EXT_Engineering.LCfg_RampTime_Visible:=			FALSE;
FB_VFD_Logic.Inp_VoltageEnabled :=									TRUE;
FB_VFD_Logic.Inp_LocalStop := 											FALSE;

// Input Parmeter
FB_VFD_Logic.Cfg_ControllerTAG:=				Cfg_ControllerTAG;
FB_VFD_Logic.Cfg_ProcessTAG:=					Cfg_ProcessTAG;
FB_VFD_Logic.Inp_AutoRunFwd:= 				Inp_AutoStartRef;
FB_VFD_Logic.Inp_AutoSpeedRef:= 			Inp_AutoSpeedRef;
FB_VFD_Logic.Inp_Interlock:= 						Inp_Interlock;
FB_VFD_Logic.Cfg_Interlock_InUse:=			Cfg_Interlock_InUse;
FB_VFD_Logic.Inp_LOTO:= 							Inp_LOTO;
FB_VFD_Logic.Cfg_LOTO_InUse:= 				Cfg_Interlock_InUse;
FB_VFD_Logic.Inp_STO:=								Inp_STO;
FB_VFD_Logic.Cfg_STO_InUse:= 					Cfg_STO_InUse;
FB_VFD_Logic.Inp_ComFault:= 					Inp_ComFault;
FB_VFD_Logic.Inp_Online:=							Inp_Online;
FB_VFD_Logic.Inp_Ready:= 							Inp_Ready;
FB_VFD_Logic.Inp_RunningFwd:= 				Inp_Running;
FB_VFD_Logic.Inp_RunningRev :=				FALSE;
FB_VFD_Logic.Inp_Error:= 							Inp_Fault;
FB_VFD_Logic.Inp_Warning:= 						Inp_Warning;
FB_VFD_Logic.Inp_Remote:=						Inp_Remote;
FB_VFD_Logic.Inp_AlmSuppress:=				Inp_AlmSuppress;
FB_VFD_Logic.Inp_AlmSuppressDesc:= 		Inp_AlmSuppressDesc;

FB_VFD_Logic.Inp_ActSpeed := ScaleTrans(SclIn:=INT_TO_REAL(Inp_Feedback), 
																				X0:=Cfg_Feedback_X0, 
																				Y0:=0, 
																				X1:=Cfg_Feedback_X1, 
																				Y1:=100);;

(*************************************************************************
 *	VFD Power, Current, Energy
 *************************************************************************)
 
 FB_VFD_Logic.Inp_Current:=0; //TODO (Scale max current to gain?)
 FB_VFD_Logic.Inp_Energy:=0;	//TODO (Scale max energy to gain?)
 FB_VFD_Logic.Inp_Power:=0; //TODO (Scale max power to gain?)
	
(*************************************************************************
 *	Runtime Statistics
 *************************************************************************)

IF Inp_Running THEN
		Wrk_Runtime := ADD_TIME(Wrk_Runtime, GetMyTaskInterval()); 
END_IF;

IF NOT  FB_VFD_Logic.Inp_ComFault THEN
		Wrk_Ontime := ADD_TIME(Wrk_Ontime, GetMyTaskInterval()); 
END_IF;

FB_VFD_Logic.Inp_VFD_TotalOnTime:= LINT_TO_UDINT( TimeToSec(Wrk_Ontime) / 3600);
FB_VFD_Logic.Inp_VFD_TotalRunTime:= LINT_TO_UDINT( TimeToSec(Wrk_Runtime) / 3600);


(*************************************************************************
 *	State and error
 *************************************************************************)
	
FB_VFD_Logic.Inp_Active_Error:= 		''; //NOT IN USE
FB_VFD_Logic.Inp_Active_Warning:= 	''; //NOT IN USE
FB_VFD_Logic.Inp_Actual_State:=		''; //NOT IN USE
	
(*************************************************************************
 *	Execute VFD Logic
 *************************************************************************)
 
FB_VFD_Logic(Ext_VFD:=Ext_VFD, 
							Int_Alarm:=Int_Alarm);

(*************************************************************************
 *	Update Outputs
 *************************************************************************)

Sts_Alarm:=					FB_VFD_Logic.Sts_AlarmTriggered;
Sts_AvailableAuto:=		FB_VFD_Logic.Sts_AvailableAuto;
Sts_Interlock := 			FB_VFD_Logic.Sts_Interlock;
Sts_RunningFwd := 		Inp_Running;

Out_Start:=					FB_VFD_Logic.Out_RunFwd;
Out_Output:= 				FB_VFD_Logic.Out_SpeedRef;
Out_OutputINT:= 		REAL_TO_INT(ScaleTrans(SclIn:=FB_VFD_Logic.Out_SpeedRef, 
																			X0:=0, 
																			Y0:=INT_TO_REAL(Cfg_Output_Y0), 
																			X1:=100, 
																			Y1:=INT_TO_REAL(Cfg_Output_Y1)));
